deepml vfx 0.3
module corpus.deepml_vfx.example_04501
policy deterministic
policy no_network
effect Effect04501 {
  coupled simulation PortalSim seed 4501 { fluid: Energy cloth: Veil particles: Sparks }
  procedural operator Distort(time, portal_state) differentiable
  cache PortalCache2 interval 0s..10s step 1/60s hash sha256("cache:04501")
  bind scene PortalScene13
  bind timeline PortalSequence3
  render_graph { Sim -> Lighting -> Distortion -> Composite }
  composite multipass [SceneColor, PortalGlow, Distortion, Atmosphere]
}

